import java.util.*;

class Solution {
    public int longestRun(int[] nums) {
        HashSet<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        int best = 0;
        for (int x : set) {
            if (set.contains(x - 1)) continue; // not the start of a run
            int y = x;
            while (set.contains(y + 1)) y++;   // walk up the run
            best = Math.max(best, y - x + 1);
        }
        return best;
    }
}

