function longestRun(nums) {
  const a = [...new Set(nums)].sort((p, q) => p - q);
  let best = 1, cur = 1;
  for (let i = 1; i < a.length; i++) { cur = a[i] === a[i - 1] + 1 ? cur + 1 : 1; best = Math.max(best, cur); }
  return best;
}
